{
    private const HEADERS = ['segment','company_name','company_website','company_location','company_industry','first_name','last_name','role','email','phone','linkedin_url','source','why_them','business_problem','qualification_notes','problem_understood','timing_understood','buyer_understood','budget_plausible','signal_key','evidence_note'];
    public function __construct(private readonly Database $database, private readonly SessionManager $session, private readonly RecordService $records, private readonly ProspectService $prospects, private readonly InteractionService $interactions, private readonly FollowUpService $followUps, private readonly OpportunityService $opportunities, private readonly Clock $clock, private readonly array $sales, private readonly string $signingKey) {}
    /** @return list<string> */ public function headers(): array { return self::HEADERS; }
    /** @param array<string,mixed>|null $file @return array<string,mixed> */
    public function preview(?array $file, int $ownerId): array
    {
        if ($file === null || (int)($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK || !is_string($file['tmp_name'] ?? null)) throw new \InvalidArgumentException('Choose a CSV file to preview.');
        if ((int)($file['size'] ?? 0) < 1 || (int)$file['size'] > 2_000_000) throw new \InvalidArgumentException('CSV files must be between 1 byte and 2 MB.');
        $raw = file_get_contents($file['tmp_name']); if (!is_string($raw) || preg_match('//u', $raw) !== 1) throw new \InvalidArgumentException('The file must be UTF-8 encoded.');
        $stream = fopen('php://temp', 'r+'); if ($stream === false) throw new \RuntimeException('Unable to read the upload.'); fwrite($stream, $raw); rewind($stream);
        $headers = fgetcsv($stream); if (!is_array($headers)) throw new \InvalidArgumentException('The CSV has no header row.');
        $headers = array_map(static fn ($v): string => trim((string)$v), $headers); $headers[0] = preg_replace('/^\xEF\xBB\xBF/', '', $headers[0]) ?? $headers[0];
        if ($headers !== self::HEADERS || count($headers) !== count(array_unique($headers))) throw new \InvalidArgumentException('Use the downloaded CSV template without changing its headers.');
        $rows=[]; $seen=[]; $number=1;
        while (($row=fgetcsv($stream)) !== false) { $number++; if (count($row) !== count($headers)) { $rows[]=['line'=>$number,'errors'=>['Expected '.count($headers).' columns.'],'data'=>[]]; continue; } if (count($rows)>=500) throw new \InvalidArgumentException('A preview is limited to 500 rows.'); $data=array_combine($headers,array_map(static fn($v):string=>trim((string)$v),$row)); $errors=array_merge($this->validateRow($data,$seen),$this->existingErrors($data)); $rows[]=['line'=>$number,'errors'=>array_values(array_unique($errors)),'data'=>$data]; }
        fclose($stream); if ($rows===[]) throw new \InvalidArgumentException('The CSV has no data rows.');
        $valid=array_values(array_filter($rows,static fn(array $row):bool=>$row['errors']===[])); $id=bin2hex(random_bytes(16)); $expires=time()+900; $hash=hash('sha256',json_encode($valid,JSON_THROW_ON_ERROR)); $token=$this->token($id,$ownerId,$hash,$expires);
        $this->session->set('csv_import_preview',['id'=>$id,'owner'=>$ownerId,'expires'=>$expires,'hash'=>$hash,'token'=>$token,'rows'=>$valid,'invalid_count'=>count($rows)-count($valid)]);
        return ['rows'=>$rows,'valid_count'=>count($valid),'invalid_count'=>count($rows)-count($valid),'token'=>$token,'expires'=>$expires];
    }
    public function commit(string $token,int $ownerId,string $correlationId): int
    {
        $plan=$this->session->get('csv_import_preview'); if (!is_array($plan) || ($plan['owner']??null)!==$ownerId || !is_string($plan['token']??null) || !hash_equals($plan['token'],$token) || (int)($plan['expires']??0)<time() || !hash_equals((string)$plan['token'],$this->token((string)$plan['id'],$ownerId,(string)$plan['hash'],(int)$plan['expires']))) throw new \DomainException('This import preview is invalid or has expired. Upload the file again.');
        $rows=$plan['rows']??[]; if ((int)($plan['invalid_count']??0)>0) throw new \DomainException('Correct every rejected row before committing an import.'); if (!is_array($rows)||$rows===[]) throw new \DomainException('There are no valid rows to import.');
        $this->database->transaction(function(PDO $pdo)use($rows,$ownerId,$correlationId):void{$companies=[];foreach($rows as $row){$this->createRow($pdo,$row['data'],$ownerId,$correlationId,$companies);}}); $this->session->remove('csv_import_preview'); return count($rows);
    }
    public function cancel():void{$this->session->remove('csv_import_preview');}
    /** @return list<string> */ public function interactionHeaders():array{return ['prospect_id','contact_id','type','direction','occurred_at','outcome','summary'];}
    /** @param array<string,mixed>|null $file @return array<string,mixed> */ public function previewInteractions(?array $file,int $ownerId):array{$rows=$this->csv($file,$this->interactionHeaders());$zone=(string)$this->database->pdo()->query('SELECT owner_timezone FROM application_settings WHERE id=1')->fetchColumn();foreach($rows as &$row){if($row['errors']!==[])continue;$data=$row['data'];$id=filter_var($data['prospect_id'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$p=$id?$this->database->pdo()->prepare('SELECT version,archived_at FROM prospects WHERE id=:id'):null;if($p){$p->execute(['id'=>$id]);$prospect=$p->fetch();}else $prospect=false;if(!$prospect||$prospect['archived_at']!==null)$row['errors'][]='Select an active existing prospect ID.';[$input,$errors]=InteractionInput::fromArray($data,$this->sales,$zone,$this->clock->now());if($input===null)$row['errors']=array_merge($row['errors'],array_values($errors));$row['prospect_version']=$prospect?(int)$prospect['version']:0;}unset($row);$valid=array_values(array_filter($rows,static fn(array $row):bool=>$row['errors']===[]));$id=bin2hex(random_bytes(16));$expires=time()+900;$hash=hash('sha256',json_encode($valid,JSON_THROW_ON_ERROR));$token=$this->token($id,$ownerId,$hash,$expires);$this->session->set('interaction_import_preview',['id'=>$id,'owner'=>$ownerId,'expires'=>$expires,'hash'=>$hash,'token'=>$token,'rows'=>$valid]);return['rows'=>$rows,'valid_count'=>count($valid),'invalid_count'=>count($rows)-count($valid),'token'=>$token];}
    public function commitInteractions(string $token,int $ownerId,string $cid):int{$plan=$this->session->get('interaction_import_preview');if(!is_array($plan)||($plan['owner']??null)!==$ownerId||!hash_equals((string)($plan['token']??''),$token)||(int)($plan['expires']??0)<time())throw new \DomainException('This import preview is invalid or has expired.');$rows=$plan['rows']??[];if(!is_array($rows)||$rows===[])throw new \DomainException('There are no valid rows to import.');$zone=(string)$this->database->pdo()->query('SELECT owner_timezone FROM application_settings WHERE id=1')->fetchColumn();$this->database->transaction(function()use($rows,$ownerId,$cid,$zone):void{foreach($rows as $row){$data=$row['data'];$id=(int)$data['prospect_id'];$s=$this->database->pdo()->prepare('SELECT version FROM prospects WHERE id=:id');$s->execute(['id'=>$id]);$version=(int)$s->fetchColumn();[$input,$errors]=InteractionInput::fromArray($data,$this->sales,$zone,$this->clock->now());if($input===null)throw new \DomainException(implode(' ', $errors));$this->interactions->record($id,$input,$version,$ownerId,$cid);}});$this->session->remove('interaction_import_preview');return count($rows);}
    /** @return list<string> */ public function followUpHeaders():array{return ['prospect_id','action','due_at'];}
    /** @param array<string,mixed>|null $file @return array<string,mixed> */ public function previewFollowUps(?array $file,int $ownerId):array{$rows=$this->csv($file,$this->followUpHeaders());$zone=new DateTimeZone((string)$this->database->pdo()->query('SELECT owner_timezone FROM application_settings WHERE id=1')->fetchColumn());foreach($rows as &$row){if($row['errors']!==[])continue;$d=$row['data'];$s=$this->database->pdo()->prepare("SELECT p.version,p.archived_at,(SELECT COUNT(*) FROM follow_ups f WHERE f.prospect_id=p.id AND f.status='open') open_count FROM prospects p WHERE p.id=:id");$s->execute(['id'=>(int)$d['prospect_id']]);$p=$s->fetch();if(!$p||$p['archived_at']!==null)$row['errors'][]='Select an active existing prospect ID.';elseif((int)$p['open_count']>0)$row['errors'][]='This prospect already has an open next action.';if(trim($d['action'])==='')$row['errors'][]='Next action is required.';$due=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$d['due_at'],$zone);if($due===false)$row['errors'][]='Enter due_at as YYYY-MM-DDTHH:MM.';}$valid=array_values(array_filter($rows,static fn(array $r):bool=>$r['errors']===[]));$id=bin2hex(random_bytes(16));$expires=time()+900;$hash=hash('sha256',json_encode($valid,JSON_THROW_ON_ERROR));$token=$this->token($id,$ownerId,$hash,$expires);$this->session->set('follow_up_import_preview',['owner'=>$ownerId,'expires'=>$expires,'token'=>$token,'rows'=>$valid]);return['rows'=>$rows,'valid_count'=>count($valid),'invalid_count'=>count($rows)-count($valid),'token'=>$token];}
    public function commitFollowUps(string $token,int $ownerId,string $cid):int{$plan=$this->session->get('follow_up_import_preview');if(!is_array($plan)||($plan['owner']??null)!==$ownerId||!hash_equals((string)($plan['token']??''),$token)||(int)($plan['expires']??0)<time())throw new \DomainException('This import preview is invalid or has expired.');$rows=$plan['rows']??[];if(!is_array($rows)||$rows===[])throw new \DomainException('There are no valid rows to import.');$zone=new DateTimeZone((string)$this->database->pdo()->query('SELECT owner_timezone FROM application_settings WHERE id=1')->fetchColumn());$this->database->transaction(function()use($rows,$ownerId,$cid,$zone):void{foreach($rows as $row){$d=$row['data'];$s=$this->database->pdo()->prepare('SELECT version FROM prospects WHERE id=:id');$s->execute(['id'=>(int)$d['prospect_id']]);$due=DateTimeImmutable::createFromFormat('!Y-m-d\TH:i',$d['due_at'],$zone);$this->followUps->schedule((int)$d['prospect_id'],$d['action'],$due->setTimezone(new DateTimeZone('UTC')),(int)$s->fetchColumn(),$ownerId,$cid);}});$this->session->remove('follow_up_import_preview');return count($rows);}
    /** @return list<string> */ public function opportunityHeaders():array{return ['prospect_id','offer_key','value_amount','expected_close_on'];}
    /** @param array<string,mixed>|null $file @return array<string,mixed> */ public function previewOpportunities(?array $file,int $ownerId):array{$rows=$this->csv($file,$this->opportunityHeaders());foreach($rows as &$row){if($row['errors']!==[])continue;$d=$row['data'];$s=$this->database->pdo()->prepare("SELECT p.status,p.archived_at,(SELECT COUNT(*) FROM opportunities o WHERE o.prospect_id=p.id AND o.stage NOT IN ('won','lost')) open_count FROM prospects p WHERE p.id=:id");$s->execute(['id'=>(int)$d['prospect_id']]);$p=$s->fetch();if(!$p||$p['archived_at']!==null)$row['errors'][]='Select an active existing prospect ID.';elseif($p['status']!=='qualified')$row['errors'][]='Only qualified prospects can enter the pipeline.';elseif((int)$p['open_count']>0)$row['errors'][]='This prospect already has an open opportunity.';if(!isset($this->sales['opportunity_offers'][$d['offer_key']]))$row['errors'][]='Select a valid offer_key.';if(!preg_match('/^\d+(\.\d{1,2})?$/',$d['value_amount']))$row['errors'][]='value_amount must be a nonnegative amount.';if($d['expected_close_on']!==''&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$d['expected_close_on']))$row['errors'][]='expected_close_on must be YYYY-MM-DD or blank.';}$valid=array_values(array_filter($rows,static fn(array $r):bool=>$r['errors']===[]));$id=bin2hex(random_bytes(16));$expires=time()+900;$hash=hash('sha256',json_encode($valid,JSON_THROW_ON_ERROR));$token=$this->token($id,$ownerId,$hash,$expires);$this->session->set('opportunity_import_preview',['owner'=>$ownerId,'expires'=>$expires,'token'=>$token,'rows'=>$valid]);return['rows'=>$rows,'valid_count'=>count($valid),'invalid_count'=>count($rows)-count($valid),'token'=>$token];}
    public function commitOpportunities(string $token,int $ownerId,string $cid):int{$plan=$this->session->get('opportunity_import_preview');if(!is_array($plan)||($plan['owner']??null)!==$ownerId||!hash_equals((string)($plan['token']??''),$token)||(int)($plan['expires']??0)<time())throw new \DomainException('This import preview is invalid or has expired.');$rows=$plan['rows']??[];if(!is_array($rows)||$rows===[])throw new \DomainException('There are no valid rows to import.');$this->database->transaction(function()use($rows,$ownerId,$cid):void{foreach($rows as $row){$d=$row['data'];$s=$this->database->pdo()->prepare('SELECT version FROM prospects WHERE id=:id');$s->execute(['id'=>(int)$d['prospect_id']]);$this->opportunities->create((int)$d['prospect_id'],['offer_key'=>$d['offer_key'],'value_amount'=>$d['value_amount'],'expected_close_on'=>$d['expected_close_on'],'attach_follow_up'=>'0'],(int)$s->fetchColumn(),$ownerId,$cid);}});$this->session->remove('opportunity_import_preview');return count($rows);}
    /** @param array<string,mixed>|null $file @param list<string> $headers @return list<array<string,mixed>> */ private function csv(?array $file,array $headers):array{if($file===null||(int)($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK||!is_string($file['tmp_name']??null))throw new \InvalidArgumentException('Choose a CSV file to preview.');$raw=file_get_contents($file['tmp_name']);if(!is_string($raw)||preg_match('//u',$raw)!==1)throw new \InvalidArgumentException('The file must be UTF-8 encoded.');$stream=fopen('php://temp','r+');fwrite($stream,$raw);rewind($stream);$actual=fgetcsv($stream);if(!is_array($actual)||array_map('trim',$actual)!==$headers)throw new \InvalidArgumentException('Use the downloaded CSV template without changing its headers.');$out=[];$line=1;while(($row=fgetcsv($stream))!==false){$line++;$out[]=['line'=>$line,'errors'=>count($row)===count($headers)?[]:['Expected '.count($headers).' columns.'],'data'=>count($row)===count($headers)?array_combine($headers,array_map(static fn($v):string=>trim((string)$v),$row)):[]];}fclose($stream);if($out===[])throw new \InvalidArgumentException('The CSV has no data rows.');return$out;}
    /** @return array<string,string> */ public function exportOptions():array{return ['campaigns'=>'Campaigns and targets','companies'=>'Companies','contacts'=>'Contacts','prospects'=>'Prospects','research_evidence'=>'Prospect research evidence','interactions'=>'Interactions','follow_ups'=>'Follow-ups','opportunities'=>'Opportunities','opportunity_history'=>'Opportunity stage history','lead_candidates'=>'Lead Finder candidates','lead_profile'=>'Ideal customer profile'];}
    /** @return array{filename:string,body:string} */ public function export(string $type):array
    {
        $queries=[
            'campaigns'=>["SELECT c.id,c.name,c.start_date,c.end_date,c.is_active,t.metric_key,t.target_value FROM campaigns c LEFT JOIN campaign_targets t ON t.campaign_id=c.id ORDER BY c.id,t.metric_key",['id','name','start_date','end_date','is_active','metric_key','target_value']],
            'companies'=>["SELECT id,name,website,location,industry,employee_range,revenue_range,notes,archived_at,created_at,updated_at FROM companies ORDER BY id",['id','name','website','location','industry','employee_range','revenue_range','notes','archived_at','created_at','updated_at']],
            'contacts'=>["SELECT ct.id,ct.company_id,c.name company_name,ct.first_name,ct.last_name,ct.role,ct.email,ct.phone,ct.linkedin_url,ct.archived_at,ct.created_at,ct.updated_at FROM contacts ct LEFT JOIN companies c ON c.id=ct.company_id ORDER BY ct.id",['id','company_id','company_name','first_name','last_name','role','email','phone','linkedin_url','archived_at','created_at','updated_at']],
            'prospects'=>["SELECT p.id,p.campaign_id,p.company_id,c.name company_name,p.primary_contact_id,CONCAT_WS(' ',ct.first_name,ct.last_name) contact_name,p.segment,p.status,p.source,p.why_them,p.business_problem,p.qualification_notes,p.problem_understood,p.timing_understood,p.buyer_understood,p.budget_plausible,p.last_contact_at,p.archived_at,p.created_at,p.updated_at FROM prospects p LEFT JOIN companies c ON c.id=p.company_id LEFT JOIN contacts ct ON ct.id=p.primary_contact_id ORDER BY p.id",['id','campaign_id','company_id','company_name','primary_contact_id','contact_name','segment','status','source','why_them','business_problem','qualification_notes','problem_understood','timing_understood','buyer_understood','budget_plausible','last_contact_at','archived_at','created_at','updated_at']],
            'research_evidence'=>["SELECT ps.id,ps.prospect_id,p.campaign_id,c.name company_name,CONCAT_WS(' ',ct.first_name,ct.last_name) contact_name,s.signal_key,s.name signal_name,ps.evidence_note,ps.observed_on,ps.created_at,ps.updated_at FROM prospect_signals ps JOIN prospects p ON p.id=ps.prospect_id LEFT JOIN companies c ON c.id=p.company_id LEFT JOIN contacts ct ON ct.id=p.primary_contact_id JOIN signals s ON s.id=ps.signal_id ORDER BY ps.id",['id','prospect_id','campaign_id','company_name','contact_name','signal_key','signal_name','evidence_note','observed_on','created_at','updated_at']],
            'interactions'=>["SELECT i.id,i.prospect_id,c.name company_name,CONCAT_WS(' ',ct.first_name,ct.last_name) prospect_contact,i.contact_id,i.type,i.direction,i.occurred_at,i.outcome,i.qualifies_as_contact,i.qualifies_as_response,i.summary,i.voided_at,i.voided_reason,i.created_at,i.updated_at FROM interactions i JOIN prospects p ON p.id=i.prospect_id LEFT JOIN companies c ON c.id=p.company_id LEFT JOIN contacts ct ON ct.id=p.primary_contact_id ORDER BY i.id",['id','prospect_id','company_name','prospect_contact','contact_id','type','direction','occurred_at','outcome','qualifies_as_contact','qualifies_as_response','summary','voided_at','voided_reason','created_at','updated_at']],
            'follow_ups'=>["SELECT f.id,f.prospect_id,o.id opportunity_id,c.name company_name,CONCAT_WS(' ',ct.first_name,ct.last_name) contact_name,f.action,f.due_at,f.status,f.completed_at,f.cancelled_at,f.cancellation_reason,f.created_at,f.updated_at FROM follow_ups f JOIN prospects p ON p.id=f.prospect_id LEFT JOIN opportunities o ON o.id=f.opportunity_id LEFT JOIN companies c ON c.id=p.company_id LEFT JOIN contacts ct ON ct.id=p.primary_contact_id ORDER BY f.id",['id','prospect_id','opportunity_id','company_name','contact_name','action','due_at','status','completed_at','cancelled_at','cancellation_reason','created_at','updated_at']],
            'opportunities'=>["SELECT o.id,o.prospect_id,c.name company_name,CONCAT_WS(' ',ct.first_name,ct.last_name) contact_name,o.offer_key,o.stage,o.value_amount,o.currency,o.expected_close_on,o.closed_at,o.lost_reason,o.created_at,o.updated_at FROM opportunities o JOIN prospects p ON p.id=o.prospect_id LEFT JOIN companies c ON c.id=p.company_id LEFT JOIN contacts ct ON ct.id=p.primary_contact_id ORDER BY o.id",['id','prospect_id','company_name','contact_name','offer_key','stage','value_amount','currency','expected_close_on','closed_at','lost_reason','created_at','updated_at']],
            'opportunity_history'=>["SELECT e.id,e.opportunity_id,o.prospect_id,c.name company_name,e.from_stage,e.to_stage,e.occurred_at,e.reason,e.voided_at,e.voided_reason,e.created_at FROM opportunity_stage_events e JOIN opportunities o ON o.id=e.opportunity_id JOIN prospects p ON p.id=o.prospect_id LEFT JOIN companies c ON c.id=p.company_id ORDER BY e.id",['id','opportunity_id','prospect_id','company_name','from_stage','to_stage','occurred_at','reason','voided_at','voided_reason','created_at']],
            'lead_candidates'=>["SELECT id,source,source_id,search_query,name,website,address,category,business_status,fit,score,evidence_json,status,reviewed_at,created_at,updated_at FROM lead_candidates ORDER BY id",['id','source','source_id','search_query','name','website','address','category','business_status','fit','score','evidence_json','status','reviewed_at','created_at','updated_at']],
            'lead_profile'=>["SELECT description,required_any_json,positive_keywords_json,negative_keywords_json,preferred_locations_json,minimum_score,strong_fit_score,updated_at FROM lead_profile WHERE id=1",['description','required_any_json','positive_keywords_json','negative_keywords_json','preferred_locations_json','minimum_score','strong_fit_score','updated_at']],
        ]; if(!isset($queries[$type]))throw new \InvalidArgumentException('Choose a valid export.'); [$sql,$headers]=$queries[$type];$rows=$this->database->pdo()->query($sql)->fetchAll();$out=fopen('php://temp','r+');fputcsv($out,$headers);foreach($rows as $row)fputcsv($out,array_map([$this,'safeCell'],array_map(static fn(string $header)=>$row[$header]??'', $headers)));rewind($out);$body=(string)stream_get_contents($out);fclose($out);return['filename'=>$type.'-'.gmdate('Y-m-d').'.csv','body'=>$body];
    }
    /** @param array<string,string> $data @param array<string,bool> $seen @return list<string> */ private function validateRow(array $data,array &$seen):array{$errors=[];$key=strtolower($data['company_name'].'|'.$data['email'].'|'.$data['first_name'].'|'.$data['last_name']);if(isset($seen[$key]))$errors[]='Duplicate of an earlier row.';$seen[$key]=true;if($data['company_name']===''&&$data['first_name']===''&&$data['last_name']==='')$errors[]='Provide a company or contact name.';if(!isset($this->sales['segments'][$data['segment']]))$errors[]='Choose a valid segment.';if($data['email']!==''&&filter_var($data['email'],FILTER_VALIDATE_EMAIL)===false)$errors[]='Email is invalid.';foreach(['problem_understood','timing_understood','buyer_understood','budget_plausible'] as $field)if(!in_array($data[$field],['','0','1'],true))$errors[]="{$field} must be blank, 0, or 1.";if(($data['signal_key']==='')!==($data['evidence_note']===''))$errors[]='Signal key and evidence note must be provided together.';if($data['signal_key']!==''&&!isset($this->sales['signals'][$data['signal_key']]))$errors[]='Signal key is invalid.';foreach($data as $value)if(strlen($value)>4000)$errors[]='A cell exceeds the allowed length.';return array_values(array_unique($errors));}
    /** @param array<string,string> $data @return list<string> */ private function existingErrors(array $data):array{$errors=[];$pdo=$this->database->pdo();if($data['company_name']!==''){$s=$pdo->prepare('SELECT 1 FROM companies WHERE archived_at IS NULL AND normalized_name=:name LIMIT 1');$s->execute(['name'=>Normalizer::comparison($data['company_name'])]);if($s->fetchColumn())$errors[]='A company with this name already exists in the CRM.';}if($data['email']!==''){$s=$pdo->prepare('SELECT 1 FROM contacts WHERE archived_at IS NULL AND email_normalized=:email LIMIT 1');$s->execute(['email'=>strtolower(trim($data['email']))]);if($s->fetchColumn())$errors[]='A contact with this email already exists in the CRM.';}return $errors;}
    /** @param array<string,string> $data @param array<string,int> $companies */ private function createRow(PDO $pdo,array $data,int $ownerId,string $correlationId,array &$companies):void{$companyId=null;$contactId=null;if($data['company_name']!==''){[$company,$errors]=CompanyInput::fromArray(['name'=>$data['company_name'],'website'=>$data['company_website'],'location'=>$data['company_location'],'industry'=>$data['company_industry']]);if($company===null)throw new \DomainException(implode(' ',$errors));$companyId=$companies[$company->normalizedName]??null;if($companyId===null){$companyId=$this->records->createCompany($company,false,$ownerId,$correlationId);$companies[$company->normalizedName]=$companyId;}}if($data['first_name']!==''||$data['last_name']!==''||$data['email']!==''){[$contact,$errors]=ContactInput::fromArray(['company_id'=>$companyId,'first_name'=>$data['first_name'],'last_name'=>$data['last_name'],'role'=>$data['role'],'email'=>$data['email'],'phone'=>$data['phone'],'linkedin_url'=>$data['linkedin_url']]);if($contact===null)throw new \DomainException(implode(' ',$errors));$contactId=$this->records->createContact($contact,false,$ownerId,$correlationId);}[$prospect,$errors]=ProspectInput::fromArray(['company_id'=>$companyId,'primary_contact_id'=>$contactId,'segment'=>$data['segment'],'source'=>$data['source'],'why_them'=>$data['why_them'],'business_problem'=>$data['business_problem'],'qualification_notes'=>$data['qualification_notes'],'problem_understood'=>$data['problem_understood'],'timing_understood'=>$data['timing_understood'],'buyer_understood'=>$data['buyer_understood'],'budget_plausible'=>$data['budget_plausible']],$this->sales);if($prospect===null)throw new \DomainException(implode(' ',$errors));$prospectId=$this->prospects->create($prospect,$ownerId,$correlationId);if($data['signal_key']!==''){$s=$pdo->prepare('SELECT id FROM signals WHERE signal_key=:key');$s->execute(['key'=>$data['signal_key']]);$signal=(int)$s->fetchColumn();$this->prospects->addSignal($prospectId,$signal,$data['evidence_note'],null,1,$ownerId,$correlationId);}}
    private function token(string $id,int $owner,string $hash,int $expires):string{return hash_hmac('sha256',$id.'|'.$owner.'|'.$hash.'|'.$expires,$this->signingKey);}
    private function safeCell(mixed $value):string{$value=(string)$value;return preg_match('/^[=+\-@]/',$value)?"'".$value:$value;}
}
